# Distance^2 to focus (2,0) minus distance^2 to line x=-2 (distance |x+2|).
# A point is on the locus iff these squared distances are equal.
def sq_dist_focus(x, y):
    return (x - 2) ** 2 + y ** 2

def sq_dist_line(x, y):
    return (x + 2) ** 2  # (|x+2|)^2, exact with no sign issue

def diff(x, y):
    return sq_dist_focus(x, y) - sq_dist_line(x, y)

# Candidate formula derived by expanding: diff = y^2 - 8x
def candidate(x, y):
    return y * y - 8 * x

# Exhaustive exact check over a finite rational grid
