mismatch = 0
on_locus = 0
checked = 0
for x in vals:
    for y in vals:
        checked += 1
        if diff(x, y) != candidate(x, y):
            mismatch += 1
        # locus membership by the original definition (equal distances)
        in_original = (sq_dist_focus(x, y) == sq_dist_line(x, y))
        in_formula = (y * y == 8 * x)
        if in_original != in_formula:
            mismatch += 1
        if in_original:
