from fractions import Fraction as F

# Submitted claim: locus of points equidistant from focus (2,0) and line x = -2 is y^2 = 8x.
# Equal distances <=> equal squared distances (both are nonnegative):
#   (x-2)^2 + y^2  ==  (x+2)^2   (distance to line x=-2 is |x+2|)
# Difference D(x,y) = (x-2)^2 + y^2 - (x+2)^2 must equal y^2 - 8x identically.

def poly_add(p, q):
    r = dict(p)
    for k, v in q.items():
        r[k] = r.get(k, 0) + v
    return {k: v for k, v in r.items() if v != 0}

def poly_mul(p, q):
    r = {}
    for (a1, b1), c1 in p.items():
        for (a2, b2), c2 in q.items():
            k = (a1 + a2, b1 + b2)
            r[k] = r.get(k, 0) + c1 * c2
    return {k: v for k, v in r.items() if v != 0}

def poly_scale(p, s):
    return {k: v * s for k, v in p.items() if v * s != 0}

# Polynomials in (x,y) as {(exp_x, exp_y): coef}
X = {(1, 0): 1}
Y = {(0, 1): 1}
const = lambda c: {(0, 0): c} if c != 0 else {}

def lin(a, poly, c):  # a*poly + c
    return poly_add(poly_scale(poly, a), const(c))

x_minus_2 = lin(1, X, -2)
x_plus_2 = lin(1, X, 2)

focus_sq = poly_add(poly_mul(x_minus_2, x_minus_2), poly_mul(Y, Y))
line_sq = poly_mul(x_plus_2, x_plus_2)
D = poly_add(focus_sq, poly_scale(line_sq, -1))

claimed_diff = poly_add(poly_mul(Y, Y), poly_scale(X, -8))

identity_ok = (D == claimed_diff)
print("Difference polynomial D =", D)
print("Claimed y^2 - 8x       =", claimed_diff)
print("Exact polynomial identity holds:", identity_ok)

# Exhaustive exact rational grid check (sampling; supports but does not alone prove)
mismatches = 0
samples = 0
on_locus = 0
rng = [F(n, 4) for n in range(-40, 41)]  # x,y in [-10,10] step 1/4
for xv in rng:
    for yv in rng:
        samples += 1
        equidistant = ((xv - 2) ** 2 + yv ** 2) == (xv + 2) ** 2
        claimed = (yv ** 2 == 8 * xv)
        if equidistant:
            on_locus += 1
        if equidistant != claimed:
            mismatches += 1

print("Grid samples:", samples, "| equidistant points found:", on_locus,
      "| mismatches:", mismatches)

# Boundary/zero checks
boundary_ok = all(
    ((F(0) - 2) ** 2 + F(0) ** 2 == (F(0) + 2) ** 2) == (F(0) ** 2 == 8 * F(0)),
    # origin: equidistant? (0-2)^2=4 vs (0+2)^2=4 -> yes; 0 = 0 -> yes
)[0] if False else True
origin_eq = ((F(0) - 2) ** 2 + F(0) ** 2) == (F(0) + 2) ** 2
origin_claim = (F(0) ** 2 == 8 * F(0))
print("Origin on locus (equidistant):", origin_eq, "| satisfies y^2=8x:", origin_claim)

if identity_ok and mismatches == 0 and origin_eq == origin_claim:
    print("CHECK PASS")
else:
