def main():
    opening = "([{<"
    closing_of = {"(": ")", "[": "]", "{": "}", "<": ">"}

    prompt_tokens = "( [ { < <".split()
    submitted_tokens = "> > } ] ]".split()

    # Exact computation: the required completion closes the still-open brackets
    # in reverse (LIFO) order. Validate the prompt first so the stack is exact.
    stack = []
    for tok in prompt_tokens:
        if tok in opening:
            stack.append(tok)
        else:
            if not stack or closing_of[stack.pop()] != tok:
                raise ValueError("prompt is not a valid bracket prefix")

    expected_tokens = [closing_of[b] for b in reversed(stack)]

    print("open_stack_bottom_to_top:", " ".join(stack))
    print("expected_completion:", " ".join(expected_tokens))
    print("submitted_completion:", " ".join(submitted_tokens))
    print("expected_length:", len(expected_tokens))
    print("submitted_length:", len(submitted_tokens))

    # Verify the submission closes everything exactly: simulate on the full sequence.
    full = prompt_tokens + submitted_tokens
    sim = []
    valid = True
    for tok in full:
        if tok in opening:
            sim.append(tok)
        else:
            if not sim or closing_of[sim.pop()] != tok:
                valid = False
                break
    if sim:
        valid = False

    mismatch_positions = [
        i for i, (e, s) in enumerate(zip(expected_tokens, submitted_tokens)) if e != s
    ]
    if len(expected_tokens) != len(submitted_tokens):
        mismatch_positions.append(min(len(expected_tokens), len(submitted_tokens)))

    print("first_mismatch_index:", mismatch_positions[0] if mismatch_positions else "none")
    print("submission_balances_sequence:", valid)

    if valid and submitted_tokens == expected_tokens:
        print("CHECK PASS")
    else:
        print("CHECK FAIL")


if __name__ == "__main__":
