PAIRS = {'(': ')', '[': ']', '{': '}', '<': '>'}
CLOSERS = {v: k for k, v in PAIRS.items()}

def compute_expected(tokens):
    """Return (expected closing tokens, error message or None) for the input prefix."""
    stack = []
    for t in tokens:
        if t in PAIRS:
            stack.append(t)
        elif t in CLOSERS:
            if not stack or stack[-1] != CLOSERS[t]:
                return None, f"input itself is invalid at token {t!r}"
            stack.pop()
        else:
            return None, f"unknown token {t!r}"
    return [PAIRS[t] for t in reversed(stack)], None

def validate_completion(input_tokens, completion_tokens):
    """Check that input + completion is fully and correctly closed. Returns (ok, reason)."""
    stack = []
    for t in input_tokens + completion_tokens:
        if t in PAIRS:
            stack.append(t)
        elif t in CLOSERS:
            if not stack:
                return False, f"closer {t!r} with empty stack"
            if stack[-1] != CLOSERS[t]:
                return False, f"closer {t!r} does not match open {stack[-1]!r}"
            stack.pop()
        else:
            return False, f"unknown token {t!r}"
    if stack:
        return False, f"unclosed openers remain: {stack}"
    return True, "all brackets matched"

input_seq = "[ [ ( [ < ( (".split()
submitted = ") ) > ] ) ] )".split()

expected, err = compute_expected(input_seq)
if err:
    print("ERROR:", err)
    print("CHECK UNKNOWN")
else:
    print("input tokens:     ", " ".join(input_seq))
    print("expected closers: ", " ".join(expected))
    print("submitted closers:", " ".join(submitted))
    print("expected length:  ", len(expected))
    print("submitted length: ", len(submitted))

