from fractions import Fraction as F

# Locus: point (x,y) equidistant from focus (4,0) and directrix x = -4.
# Squared distance to focus: (x-4)^2 + y^2
# Squared distance to line:  (x+4)^2   (distance |x+4|, so compare squares since both are >= 0)
# Identity: [(x-4)^2 + y^2] - (x+4)^2 = y^2 - 16x  (exact polynomial identity)

def focus_sq(x, y):
    return (x - 4) ** 2 + y ** 2

def line_sq(x, y):
    return (x + 4) ** 2

def equidistant(x, y):
    return focus_sq(x, y) == line_sq(x, y)

# Exact identity check over a rational grid
grid_x = [F(k, 4) for k in range(-40, 161)]
grid_y = [F(k, 4) for k in range(-80, 81)]

identity_ok = True
for x in grid_x:
    for y in grid_y:
        if focus_sq(x, y) - line_sq(x, y) != y * y - 16 * x:
            identity_ok = False
print("Identity [(x-4)^2+y^2]-(x+4)^2 = y^2-16x on grid:", identity_ok)
print("CHECK PASS" if identity_ok else "CHECK FAIL")

