true_valid = True
true_complete = True
for x in grid_x:
    for y in grid_y:
        on_true = (y * y == 16 * x)
        if on_true != equidistant(x, y):
            true_valid = False
            true_complete = False
print("Locus y^2=16x matches equidistance on grid:", true_valid and true_complete)
print("CHECK PASS" if (true_valid and true_complete) else "CHECK FAIL")

# Submitted answer y^2 = 20x: search grid for counterexample
counterexample = None
for x in grid_x:
    for y in grid_y:
        if y * y == 20 * x and not equidistant(x, y):
            counterexample = (x, y)
            break
    if counterexample:
