        if len(out) == n:
            if not st:
                found.append(tuple(out))
            return
        remaining = n - len(out)
        if len(st) > remaining:
            return
        for c in CLOSER_SYMBOLS:
            if st and PAIRS[st[-1]] == c:
                dfs(st[:-1], out + [c])

