    """Return (stack_after_prefix, error_message) for an input token list."""
    stack = []
    for t in tokens:
        if t in PAIRS:
            stack.append(t)
        elif t in CLOSERS:
            if not stack or stack[-1] != CLOSERS[t]:
                return stack, f"input itself is invalid at closer {t!r}"
            stack.pop()
        else:
            return stack, f"unknown token {t!r}"
